"""Document-review process capture, not an execution sandbox or product gate."""
import base64,datetime,hashlib,json,os,re,shutil,subprocess,traceback
from pathlib import Path
from hermes_tools import write_file
JOURNAL_BASE=Path('F:/ChnobelRuntime/review-journals/guard-policy-01-round04')
PYTHON='F:/ChnobelRuntime/venv/Scripts/python.exe'
OVERRIDES={'PYTHONDONTWRITEBYTECODE':'1','PYTHONIOENCODING':'utf-8','GIT_OPTIONAL_LOCKS':'0','GIT_TERMINAL_PROMPT':'0','TEMP':'F:/ChnobelRuntime/tmp','TMP':'F:/ChnobelRuntime/tmp','TMPDIR':'F:/ChnobelRuntime/tmp','UV_CACHE_DIR':'F:/ChnobelRuntime/cache/uv'}
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def digest(raw):return hashlib.sha256(raw).hexdigest()
def binding(path):
 raw=Path(path).read_bytes();return {'path':Path(path).as_posix(),'sha256':digest(raw),'bytes':len(raw)}
def save_new(path,value):
 path=Path(path)
 if path.exists():raise FileExistsError('No overwrite or blind rerun: '+path.as_posix())
 text=json.dumps(value,ensure_ascii=False,indent=2)+'\n'
 result=write_file(path.as_posix(),text)
 if result.get('verified') is not True:raise RuntimeError({'writeRefused':result,'path':path.as_posix()})
 assert path.read_bytes()==text.encode('utf-8')
 return binding(path)
def stream(raw):
 return {'base64':base64.b64encode(raw).decode('ascii'),'utf8Display':raw.decode('utf-8',errors='replace'),'sha256':digest(raw),'bytes':len(raw),'utf8Exact':raw.decode('utf-8',errors='replace').encode('utf-8')==raw}
def run(operation_path):
 op_path=Path(operation_path).resolve()
 assert op_path.parent.parent==JOURNAL_BASE.resolve()
 assert op_path.parent.name in {'preflight','redteam'}
 assert re.fullmatch(r'[0-9]{4}\.operation\.json',op_path.name)
 op_bytes=op_path.read_bytes();op=json.loads(op_bytes);stem=op_path.name[:4]
 assert op['id']==stem and op['mode'] in {'python','bash_syntax'}
 code=op['code'];assert isinstance(code,str) and len(code.encode('utf-8'))<=12000
 timeout=op['timeoutSeconds'];assert isinstance(timeout,int) and 1<=timeout<=180
 request_path=op_path.parent/(stem+'.request.json');result_path=op_path.parent/(stem+'.result.json')
 if request_path.exists() or result_path.exists():raise FileExistsError('Existing request/result; inspect it, never rerun this ID')
 if op['mode']=='python':argv=[PYTHON,'-B','-c',code]
 else:
  assert op_path.parent.name=='preflight','Shell mode only for bounded parent syntax probe'
  bash=shutil.which('bash');assert bash is not None
  argv=[bash,'--noprofile','--norc','-n','-c',code]
 env=dict(os.environ)
 removed=[key for key in ['BASH_ENV','ENV','PYTHONPATH','PYTHONSTARTUP'] if key in env]
 for key in removed:env.pop(key)
 env.update(OVERRIDES)
 command_line=subprocess.list2cmdline(argv)
 assert len(command_line.encode('utf-16-le'))//2<30000
 request={'kind':'document-process-request/1','id':stem,'preparedAt':now(),'operation':binding(op_path),'operationUtf8Raw':op_bytes.decode('utf-8'),'captureDriver':binding(__file__),'argv':argv,'windowsCommandLine':command_line,'cwd':op_path.parent.as_posix(),'shell':False,'captureOutput':True,'timeoutSeconds':timeout,'environmentOverrides':OVERRIDES,'removedEnvironmentKeys':removed,'remainingEnvironment':'Inherited, not logged; no claim of complete environment attestation','innerCode':{'utf8Raw':code,'sha256':digest(code.encode('utf-8')),'bytes':len(code.encode('utf-8'))},'isProductExecution':False,'executionSandboxClaimed':False}
 request_bound=save_new(request_path,request)
 assert json.loads(request_path.read_bytes())==request and op_path.read_bytes()==op_bytes
 started=now();exception=None;exit_code=None;out=b'';err=b'';state='SPAWN_ERROR'
 try:
  completed=subprocess.run(request['argv'],cwd=request['cwd'],env=env,shell=False,capture_output=True,timeout=request['timeoutSeconds'])
  exit_code=completed.returncode;out=completed.stdout;err=completed.stderr;state='COMPLETED'
 except subprocess.TimeoutExpired as ex:
  out=ex.stdout or b'';err=ex.stderr or b'';exception=traceback.format_exc();state='TIMEOUT'
 except Exception:
  exception=traceback.format_exc()
 result={'kind':'document-process-result/1','id':stem,'request':request_bound,'startedAt':started,'finishedAt':now(),'state':state,'exitCode':exit_code,'stdout':stream(out),'stderr':stream(err),'controllerException':exception,'requestStillMatches':binding(request_path)==request_bound,'captureDriver':binding(__file__),'productExecution':'NOT_RUN','scope':'Only this process request and its actual streams; not crash durability or independent execution authentication'}
 result_bound=save_new(result_path,result)
 total=len(out)+len(err)+(len(exception.encode('utf-8')) if exception else 0)
 response={'id':stem,'state':state,'exitCode':exit_code,'request':request_bound,'result':result_bound,'stdoutBytes':len(out),'stderrBytes':len(err),'fullDisplay':total<=8000}
 if total<=8000:response.update({'stdout':result['stdout']['utf8Display'],'stderr':result['stderr']['utf8Display'],'controllerException':exception})
 else:response['display']='WITHHELD: full streams preserved in result file; read bounded semantic sections'
 return response
